INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (364545, 15486, 'South China Morning Post', 'en', 'Russia summons Japan ambassador over disputed Kuril Islands row after Putin visit', 'https://www.scmp.com/news/world/russia-central-asia/article/3364347/russia-summons-japan-ambassador-over-disputed-kuril-islands-row-after-putin-visit', 'Moscow said on Monday it had summoned the Japanese ambassador after Tokyo condemned President Vladimir Putin’s recent visit to Russia’s far-eastern Kuril Islands, which are also claimed by Japan. Russian-Japanese relations have long been dogged by the contested islands, known in Japan as the Northern Territories and seized by the Soviet Union in 1945. Putin, 73, travelled to the islands after visiting the nearby Russian island of Sakhalin, prompting Japan to summon Russia’s ambassador in...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/ddb5005a-c448-4295-88c2-331ae43d2441_e317b8f3.jpg?itok=TkAkp0HS&v=1787005632', '2026-08-17T22:30:14+00:00', '2026-08-17T22:40:06.366504'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
